impl LookupReferences for Appointment {
    fn lookup_references(&mut self) -> Vec<Box<&mut dyn ReferenceField>> {
        let mut refs: Vec<Box<&mut dyn ReferenceField>> = Vec::new();
        for indication in self.0.indication.iter_mut() {
            if let Some(indication) = indication.as_mut() {
                refs.push(Box::new(indication));
            }
        }
        for supporting_information in self.0.supporting_information.iter_mut() {
            if let Some(supporting_information) = supporting_information.as_mut() {
                refs.push(Box::new(supporting_information));
            }
        }
        for slot in self.0.slot.iter_mut() {
            if let Some(slot) = slot.as_mut() {
                refs.push(Box::new(slot));
            }
        }
        for incoming_referral in self.0.incoming_referral.iter_mut() {
            if let Some(incoming_referral) = incoming_referral.as_mut() {
                refs.push(Box::new(incoming_referral));
            }
        }
        for participant in self.0.participant.iter_mut() {
            if let Some(participant) = participant.as_mut() {
                refs.extend(participant.lookup_references());
            }
        }
        refs
    }
}
