impl LookupReferences for Claim {
    fn lookup_references(&mut self) -> Vec<Box<&mut dyn ReferenceField>> {
        let mut refs: Vec<Box<&mut dyn ReferenceField>> = Vec::new();
        if let Some(patient) = self.0.patient.as_mut() {
            refs.push(Box::new(patient));
        }
        if let Some(enterer) = self.0.enterer.as_mut() {
            refs.push(Box::new(enterer));
        }
        if let Some(insurer) = self.0.insurer.as_mut() {
            refs.push(Box::new(insurer));
        }
        if let Some(provider) = self.0.provider.as_mut() {
            refs.push(Box::new(provider));
        }
        if let Some(organization) = self.0.organization.as_mut() {
            refs.push(Box::new(organization));
        }
        for related in self.0.related.iter_mut() {
            if let Some(related) = related.as_mut() {
                refs.extend(related.lookup_references());
            }
        }
        if let Some(prescription) = self.0.prescription.as_mut() {
            refs.push(Box::new(prescription));
        }
        if let Some(original_prescription) = self.0.original_prescription.as_mut() {
            refs.push(Box::new(original_prescription));
        }
        if let Some(payee) = self.0.payee.as_mut() {
            refs.extend(payee.lookup_references());
        }
        if let Some(referral) = self.0.referral.as_mut() {
            refs.push(Box::new(referral));
        }
        if let Some(facility) = self.0.facility.as_mut() {
            refs.push(Box::new(facility));
        }
        for care_team in self.0.care_team.iter_mut() {
            if let Some(care_team) = care_team.as_mut() {
                refs.extend(care_team.lookup_references());
            }
        }
        for information in self.0.information.iter_mut() {
            if let Some(information) = information.as_mut() {
                refs.extend(information.lookup_references());
            }
        }
        for diagnosis in self.0.diagnosis.iter_mut() {
            if let Some(diagnosis) = diagnosis.as_mut() {
                refs.extend(diagnosis.lookup_references());
            }
        }
        for procedure in self.0.procedure.iter_mut() {
            if let Some(procedure) = procedure.as_mut() {
                refs.extend(procedure.lookup_references());
            }
        }
        for insurance in self.0.insurance.iter_mut() {
            if let Some(insurance) = insurance.as_mut() {
                refs.extend(insurance.lookup_references());
            }
        }
        if let Some(accident) = self.0.accident.as_mut() {
            refs.extend(accident.lookup_references());
        }
        for item in self.0.item.iter_mut() {
            if let Some(item) = item.as_mut() {
                refs.extend(item.lookup_references());
            }
        }
        refs
    }
}
