impl LookupReferences for Communication {
    fn lookup_references(&mut self) -> Vec<Box<&mut dyn ReferenceField>> {
        let mut refs: Vec<Box<&mut dyn ReferenceField>> = Vec::new();
        for definition in self.0.definition.iter_mut() {
            if let Some(definition) = definition.as_mut() {
                refs.push(Box::new(definition));
            }
        }
        for based_on in self.0.based_on.iter_mut() {
            if let Some(based_on) = based_on.as_mut() {
                refs.push(Box::new(based_on));
            }
        }
        for part_of in self.0.part_of.iter_mut() {
            if let Some(part_of) = part_of.as_mut() {
                refs.push(Box::new(part_of));
            }
        }
        if let Some(subject) = self.0.subject.as_mut() {
            refs.push(Box::new(subject));
        }
        for recipient in self.0.recipient.iter_mut() {
            if let Some(recipient) = recipient.as_mut() {
                refs.push(Box::new(recipient));
            }
        }
        for topic in self.0.topic.iter_mut() {
            if let Some(topic) = topic.as_mut() {
                refs.push(Box::new(topic));
            }
        }
        if let Some(context) = self.0.context.as_mut() {
            refs.push(Box::new(context));
        }
        if let Some(sender) = self.0.sender.as_mut() {
            refs.push(Box::new(sender));
        }
        for reason_reference in self.0.reason_reference.iter_mut() {
            if let Some(reason_reference) = reason_reference.as_mut() {
                refs.push(Box::new(reason_reference));
            }
        }
        for payload in self.0.payload.iter_mut() {
            if let Some(payload) = payload.as_mut() {
                refs.extend(payload.lookup_references());
            }
        }
        refs
    }
}
