impl LookupReferences for DiagnosticReport {
    fn lookup_references(&mut self) -> Vec<Box<&mut dyn ReferenceField>> {
        let mut refs: Vec<Box<&mut dyn ReferenceField>> = Vec::new();
        for based_on in self.0.based_on.iter_mut() {
            if let Some(based_on) = based_on.as_mut() {
                refs.push(Box::new(based_on));
            }
        }
        if let Some(subject) = self.0.subject.as_mut() {
            refs.push(Box::new(subject));
        }
        if let Some(context) = self.0.context.as_mut() {
            refs.push(Box::new(context));
        }
        for performer in self.0.performer.iter_mut() {
            if let Some(performer) = performer.as_mut() {
                refs.extend(performer.lookup_references());
            }
        }
        for specimen in self.0.specimen.iter_mut() {
            if let Some(specimen) = specimen.as_mut() {
                refs.push(Box::new(specimen));
            }
        }
        for result in self.0.result.iter_mut() {
            if let Some(result) = result.as_mut() {
                refs.push(Box::new(result));
            }
        }
        for imaging_study in self.0.imaging_study.iter_mut() {
            if let Some(imaging_study) = imaging_study.as_mut() {
                refs.push(Box::new(imaging_study));
            }
        }
        for image in self.0.image.iter_mut() {
            if let Some(image) = image.as_mut() {
                refs.extend(image.lookup_references());
            }
        }
        refs
    }
}
