impl LookupReferences for Sequence {
    fn lookup_references(&mut self) -> Vec<Box<&mut dyn ReferenceField>> {
        let mut refs: Vec<Box<&mut dyn ReferenceField>> = Vec::new();
        if let Some(patient) = self.0.patient.as_mut() {
            refs.push(Box::new(patient));
        }
        if let Some(specimen) = self.0.specimen.as_mut() {
            refs.push(Box::new(specimen));
        }
        if let Some(device) = self.0.device.as_mut() {
            refs.push(Box::new(device));
        }
        if let Some(performer) = self.0.performer.as_mut() {
            refs.push(Box::new(performer));
        }
        if let Some(reference_seq) = self.0.reference_seq.as_mut() {
            refs.extend(reference_seq.lookup_references());
        }
        for variant in self.0.variant.iter_mut() {
            if let Some(variant) = variant.as_mut() {
                refs.extend(variant.lookup_references());
            }
        }
        for quality in self.0.quality.iter_mut() {
            if let Some(quality) = quality.as_mut() {
                refs.extend(quality.lookup_references());
            }
        }
        for repository in self.0.repository.iter_mut() {
            if let Some(repository) = repository.as_mut() {
                refs.extend(repository.lookup_references());
            }
        }
        for pointer in self.0.pointer.iter_mut() {
            if let Some(pointer) = pointer.as_mut() {
                refs.push(Box::new(pointer));
            }
        }
        refs
    }
}
